  'settings.reconnect.routerFound': '{address} aurkitu da.',
  'settings.reconnect.routerFoundVia': '{address} aurkitu da {iface} bidez. Merezi du begiratzea: edukiontzi batean hori sarritan zubia izaten da, ez bideratzailea.',
  'settings.reconnect.routerFailed': 'Hemen ezin izan da bideratzailearen helbiderik irakurri: {reason}',
  'settings.reconnect.username': 'Bideratzailearen erabiltzaile-izena',
  'settings.reconnect.usernameHint': 'Bideratzailerako sarbidea, ez ostalari bateko kontua. Horretara zabaltzen da %%username%%.',
  'settings.reconnect.password': 'Bideratzailearen pasahitza',
  'settings.reconnect.passwordStored': 'gordeta, eta ez da inoiz hona itzultzen',
  'settings.reconnect.passwordHint': 'Gordetako pasahitza ez da inoiz orri honetara itzultzen, eta horregatik dago kutxa hutsik: utzi hutsik eta gordetakoak hor jarraituko du. Idatzi berri bat ordezkatzeko. Erabat kentzeko, idatzi zerbait eta gero hustu kutxa berriro.',

  'settings.reconnect.requests': 'Eskaerak',
  'settings.reconnect.requestsHint': 'Hurrenez hurren jotzen dira, eta exekuzioa bideratzaileak erantzuten ez dion lehenengoan gelditzen da. JDownloader-en LiveHeader metodoa da: normalean saio-hasiera bat, gero berrabiaraztea edo deskonektatzea. Eremu guztiek onartzen dituzte aldagaiak.',
  'settings.reconnect.requestsEmpty': 'Oraindik ez dago eskaerarik. Gehitu bat, edo itsatsi grabatutako script bat.',
