  'settings.reconnect.requestHeaders': 'Goiburuak',
  'settings.reconnect.requestHeadersHint': 'Lerro bakoitzeko bat, Izena: balioa moduan. Host goiburua errespetatzen da eta benetan kablera iristen da, eta hori behar dute administrazio orria ostalari birtual gisa zerbitzatzen duten bideratzaileen firmwareek.',
  'settings.reconnect.requestBody': 'Gorputza',
  'settings.reconnect.requestBodyHint': 'Dagoen bezala bidaltzen da. Eduki mota propiorik gabeko gorputz bat inprimaki bidalketa gisa ateratzen da, eta grabatutako bideratzaile saio-hasiera bat horixe da hain zuzen.',

  'settings.reconnect.import': 'Inportatu script bat',
  'settings.reconnect.importLabel': 'LiveHeader edo curl scripta',
  'settings.reconnect.importHint': 'Itsatsi JDownloader-en birkonexio script bat, markak eta guzti. Haren aldagaiak sartzean itzultzen dira, eta %%%routerip%%% bideratzailearen helbidea bihurtzen da, ez publikoa, hemen bi gauza desberdin baitira.',
  'settings.reconnect.importRead': 'Irakurri scripta',
