  'settings.reconnect.importBlocked': 'Baztertutako lerro bat duen script batetik ez da ezer hartzen. Bideratzaile script erdi bat berrabiarazterik gabeko saio-hasiera bat da, eta hori egun batzuk geroago ikusten da, inoiz aldatzen ez den helbide baten moduan.',
  'settings.reconnect.importFailed': 'Ezin izan da scripta irakurri: {reason}',

  'settings.reconnect.checkTitle': 'Helbidea egiaztatzea',
  'settings.reconnect.checkUrl': 'IP egiaztapenaren URLa',
  'settings.reconnect.checkUrlHint': 'Metodoa exekutatu aurretik eskuratzen da, eta berriro ondoren; exekuzioa amaitutzat jotzen da erakusten duen helbidea aldatu bezain laster. Ez dago balio lehenetsirik: zeuk ostatatzen duzun deskarga-kudeatzaile batek ez luke zure helbidea inoiz aukeratu ez duzun zerbitzu bati jakinarazten hasi behar. Erakusten duenak internetek ikusten duen helbidea izan behar du, zure sareko helbidea itzultzen duen orri batek ezin baitu birkonexio bat ezer egin ez duen exekuzio batetik bereizi.',
  'settings.reconnect.checkPresets': 'Zerbitzu ezagunak',
  'settings.reconnect.checkPresetsHint': 'Lasterbide bat lehentasunik ez duenarentzat, ez balio lehenetsia: bat ere ez da zure ordez hautatzen, eta zure helbide publikoa erakusten duen edozein orrik berdin-berdin balio du.',
  'settings.reconnect.interval': 'Egiaztapenen arteko segundoak (1etik 60ra)',
  'settings.reconnect.intervalHint': 'Zenbat itxaron behar den egiaztapen URLari bi begiraldi ematen zaizkion bitartean, metodoa exekutatu ondoren. Beheko muga bat dago, muga hori gabeko begizta batek egiaztapen zerbitzua jomuga bihurtzen duelako.',
  'settings.reconnect.timeout': 'Egiaztatzen jarraitzeko segundoak (5etik 900era)',
  'settings.reconnect.timeoutHint': 'Zenbat denbora begiratzen jarraitu exekuzioa huts egindakotzat jo aurretik. Ordu laurden geroago oraindik zain dagoen birkonexio batek huts egin du, hemen dena delakoa idatzita egonda ere. Tarteak baino txikiagoa den denbora muga tarteraino igotzen da, bestela exekuzioa egiaztapen bakar bat ere gertatu aurretik amaituko litzateke.',
  'settings.reconnect.clamped': '{n} gisa gorde da.',

