  'settings.module.ytdlp': 'yt-dlp',
  'settings.resolvers.moduleUnavailable': 'Modulua ez dago erabilgarri',
  'settings.resolvers.moduleUnavailableHint': 'Beheko guztia gordetzen da hala ere, eta yt-dlp erabilgarri dagoen unean hartzen du eragina. Orain aldatzen duzun ezer ez da galtzen.',
  'settings.resolvers.about': 'yt-dlp backendaren konfigurazioa. Backend horrek yt-dlp-k berak onartzen dituen multimedia- eta streaming-guneetatik deskargatzen du. Esteka bat zein zerbitzuk kudeatzen duen (yt-dlp-k, debrid kontu batek edo JDownloader backendak) Kontuak orriko lehentasun-ordenak erabakitzen du. Orri honetan ezartzen da zer egiten duen yt-dlp-k esteka bat hara bideratu ondoren.',
  'settings.resolvers.quality': 'Kalitatea',
  'settings.resolvers.videoFormat': 'Bideo formatua',
  'settings.resolvers.qualityHint': 'yt-dlp abiaraztean zein -f hautatzaile erabiltzen den. Erabilgarri dagoen onena yt-dlp-ren berezko lehenetsia da, eta ezarpen hau existitu aurretik deskarga bakoitzak erabiltzen zuena.',
  'settings.resolvers.quality.best': 'Erabilgarri dagoen onena',
