  'settings.resolvers.customFormatHint': 'yt-dlp-ren berezko -f balioa, adib. bestvideo[height<=720]+bestaudio/best. Egiaztatu gabe pasatzen da; yt-dlp-k baztertzen duen balioak zereginean bere errorearekin huts egiten du.',
  'settings.resolvers.playlist': 'Deskargatu erreprodukzio-zerrenda osoa esteka batek horren barrura seinalatzen duenean',
