  'settings.torrents.notApplied': 'Build honek ez ditu oraindik aplikatzen beheko ezarpenetako bi. Igotze muga gorde eta egiaztatu egiten da, baina motorrak ezin dio martxan dagoen deskarga bati aplikatu. DHT eta PEX ere ez dira torrent arrunt batera iristen: biak piztuta dituela egiten du seed, hemen ezarritakoa edozein dela ere. Torrent pribatu batek beste modu batera funtzionatzen du, Peer aurkikuntza ataleko (i) ikurrak azaltzen duen bezala.',
  'onboarding.step': '{n}. urratsa / {total}',
  'onboarding.skip': 'Saltatu',
  'onboarding.back': 'Atzera',
  'onboarding.next': 'Hurrengoa',
  'onboarding.finish': 'Eginda',
  'onboarding.welcome.title': 'Ongi etorri KnightLoader-era',
  'onboarding.welcome.body': 'KnightLoader zeuk ostatatzen duzun deskarga-kudeatzaile bat da. Itsatsi edo jaregin esteka bat, eta dagokion backendak ekarriko du: barneko motorra fitxategi-esteka arruntetarako, yt-dlp multimedia-orrietarako, debrid zerbitzu bat dagoeneko ordaintzen dituzun ostalarietarako, edo interfazerik gabeko JDownloader bat gainerako guztirako. Bira labur honek hasi aurretik egiaztatzea merezi duen ezarpen bakarra erakusten du.',
  'onboarding.welcome.langLabel': 'Interfazearen hizkuntza',
  'onboarding.folder.title': 'Non egon behar dute fitxategiek?',
  'onboarding.folder.body': 'Hau da amaitutako deskargak idazten diren karpeta. Idatzi bide bat edo arakatu zerbitzaria bat aukeratzeko. Edonoiz alda dezakezu berriro Orokorra ezarpen-orritik.',
  'onboarding.accounts.title': 'Premium ostalariak, nahi dituzunean',
  'onboarding.accounts.body': 'Ilarak konturik gabe ere funtzionatzen du. Dagoeneko ordaintzen duzun ostalari edo debrid zerbitzu batean abiadura osoa nahi duzunean, gehitu haren saio-hasiera Kontuak atalean. Ez duzu horietako ezer orain konfiguratu behar.',
  'onboarding.accounts.link': 'Ireki Kontuak',
  'onboarding.finished.title': 'Prest zaude',
  'onboarding.finished.body': 'Honekin amaitzen da bira. Ezarpenetako Laguntza orriak bertsio honek egiten duen gainerako guztiaren azalpen osoa du, eta kontrol gehienek beren azalpena daramate (i) ikono baten atzean.',

