  'settings.resolvers.presetHostHint': 'Balio hauek zein gunetan aplikatzen diren, adibidez youtube.com. Minuskulaz eta hasierako «www.» gabe gordetzen da, eta helbide oso bat itsatsi ere egin daiteke: ostalaria bakarrik gordetzen da. Bideo-gune handientzat sarrera batek beren beste helbideak ere hartzen ditu: youtube.com-ek youtu.be eta m.youtube.com ere hartzen ditu. Hemen sarrerarik ez duen ostalari batek aldaera guztiak aktibatuta hasten ditu, kalitate onenean.',
