  'settings.feeds.lastPolledHint': 'Harpidetza honi azkenekoz noiz begiratu zitzaion, begiratzeak funtzionatu zuen ala ez. Zerbitzaria berrabiaraztean galdu egiten da datu hori, harpidetzak jada gehitu duena ez ordea; beraz hilabeteetan jarraitu duzun feed batek egiaztatu gabe ematen du berrabiarazi osteko segundo gutxi horietan.',
  'settings.feeds.pollFailed': 'Azken egiaztapenak huts egin du',
