  'settings.feeds.seededHint': 'Harpidetza berri baten lehen egiaztapenak feedak une horretan daraman guztia idazten du ezagun gisa, eta ez du bat ere gehitzen, argitaratzailearen artxibo osoa batera erori ez dakizun. Handik aurrera agertzen dena bakarrik gehitzen da.',
  'settings.feeds.remembered': '{n} sarrera gogoratuta',
  'settings.feeds.rememberedHint': 'Harpidetza honek zenbat sarrera ezagutzen dituen berriro, feedak oraindik ematen dituen bitartean bigarren aldiz gehi ez daitezen. Gehienez 500 harpidetzako; zaharrenak erortzen dira lehenik, eta feedean oraindik dagoen sarrera bat ez da inoiz horien artean egoten.',
  'settings.feeds.test': 'Probatu',
  'settings.feeds.testBusy': 'Eskuratzen…',
  'settings.feeds.testHint': 'Helbide hau behin eskuratzen du eta zer daraman erakusten dizu, zure iragazkia zein izenbururen aurka probatzen den ikus dezazun. Irakurri baino ez du egiten: ez da ezer biltzailera gehitzen eta ez da ezer ikusi gisa idazten, beraz oraindik gorde ez duzun helbide batekin ere saka dezakezu.',
  'settings.feeds.testResult': 'Feed honek zer daraman',
