  'settings.feeds.testEmpty': 'Helbideak erantzun du, baina dokumentuak ez darama sarrerarik batere. Egiaztatu benetan feed bat dela eta ez feeda dagoen orria.',
  'settings.feeds.testFailed': 'Ezin izan da feed hau irakurri',
  'settings.headerProfiles.title': 'Goiburu-profilak',
  'settings.headerProfiles.hint': 'Gune batzuek saioa hasita duen nabigatzaile bati bakarrik ematen diote fitxategia, edo deia beren orrietako batetik datorrenean bakarrik. Profil batek gune bakar bateko goiburuak gordetzen ditu, zure kontuen gakoak bezalaxe zifratuta, eta KnightLoader-ek gune horretako deskarga bakoitzarekin bidaltzen ditu.',
  'settings.headerProfiles.empty': 'Oraindik ez dago goiburu-profilik.',
  'settings.headerProfiles.emptyHint': 'Bat izateak merezi du deskarga bat nabigatzailean saioa hasita zauden bitartean bakarrik dabilenetik aurrera.',
  'settings.headerProfiles.add': 'Gehitu profila',
  'settings.headerProfiles.name': 'Profilaren izena',
  'settings.headerProfiles.nameHint': 'Izen honen bidez deitzen diozu profil honi, Packagizer arau batean zein hemen. Letrak, zenbakiak eta - _ edo . bakarrik.',
  'settings.headerProfiles.namePlaceholder': 'adib. foroa',
  'settings.headerProfiles.origin': 'Gunea',
  'settings.headerProfiles.originHint': 'Itsatsi goiburuak kopiatu dituzun orriaren helbidea. Beste ataka bat, eta http https-en ordez, beste gune bat dira eta beren profila behar dute. Azpidomeinu bat ez dago domeinu nagusiaren profilak estalita.',
  'settings.headerProfiles.headers': 'Goiburuak',
  'settings.headerProfiles.headerName': 'Izena',
  'settings.headerProfiles.headerValue': 'Balioa',
  'settings.headerProfiles.valueStored': 'Gordeta',
  'settings.headerProfiles.valueStoredHint': 'Balioa instantzia honetan geratzen da eta ez da inoiz orri honetara itzultzen. Utzi eremua dagoen bezala hura mantentzeko, edo idatzi balio berri bat hura ordezkatzeko.',
  'settings.headerProfiles.error.originInvalid': 'Hori ez da http edo https helbide bat. Itsatsi gunearen helbidea, adibidez https://forum.example.org.',
  'settings.headerProfiles.error.originTaken': '«{profile}» profilak jada hartzen du gune hau. Editatu hura, edo ezabatu lehenik.',
  'settings.headerProfiles.error.nameNeeded': 'Oraindik ez dago gune hau hartzen duen profilik, beraz eman izen bat honi.',
  'settings.headerProfiles.error.nameInvalid': 'Profil-izen batek letrak, zenbakiak eta - _ edo . bakarrik izan ditzake, gehienez 64 karaktere.',
  'settings.headerProfiles.error.noHeaders': 'Gehitu gutxienez balioa duen goiburu bat, edo ezabatu profila.',
  'settings.headerProfiles.addHeader': 'Gehitu goiburua',
  'settings.headerProfiles.removeHeader': 'Kendu goiburu hau',
  'settings.headerProfiles.count': '{n} goiburu',
  'settings.headerProfiles.save': 'Gorde profila',
  'settings.headerProfiles.delete': 'Ezabatu profila',
  'settings.headerProfiles.deleteConfirm': '{id} profila ezabatu? Barruan dituen goiburuak desagertu egingo dira, eta {origin} gunetik egiten diren deskargak berriro haiek gabe bidaliko dira.',
  'settings.rules.action.category': 'Kategoria',
  'settings.rules.action.categoryHint': 'Bat datozen estekak orri honetan beherago dagoen Kategoriak zerrendako tiraderetako batean sailkatzen ditu, eta tiradera horrek bere karpeta, bere ilarako lekua, bere erauzteko etengailua eta bere talka-araua dakartza berekin. Ukitu gabe utzita, arau honek ez du horri buruz iritzirik eta esteka sailkatu gabe geratzen da. Arau honek deskargen karpeta bat ere izendatzen badu, karpeta horrek irabazten du eta tiraderak gainerako guztia jartzen du. Ezabatuta dagoen tiradera bat izendatzea gordetzean baztertzen da, ez dagoen tiradera bati begira dagoen arau batek ez baitu ezertxo ere egiten bat datorren esteka bakoitzarekin, mezurik eman gabe.',
  'settings.rules.action.categoryNone': 'Oraindik ez dago kategoriarik. Sortu bat lehenik orri honetan beherago, Kategoriak atalean; bestela arau honek existitzen ez den tiradera batean sailkatuko lituzke estekak.',
  'settings.rules.action.categoryMissing': '{id} (ezabatuta)',
  'settings.resolvers.cookieJars': 'Gordetako fitxategiak',
  'settings.resolvers.cookieJarsHint': 'Gordetako fitxategi bat ez da inoiz berriro erakusten: saioa hasita duen sesio bat da, eta horregatik norabide bakarrean egiten du bidea, zerbitzari honetara. Bat ordezkatzeko, itsatsi fitxategi berria haren gainean.',
