  'detail.label': 'Zereginaren xehetasunak',
  'detail.link': 'Esteka',
  'detail.address': 'Helbidea',
  'detail.addressHint': 'Deskarga hau zein helbidetatik abiatu zen. Aplikazioak eskatu zuena da, eta hori ez da beti byteak nondik etorri diren: debrid zerbitzu baten bidez, beheko ostalaria fitxategia dagoen gunea da, eta backenda fitxategia ekarri duena.',
  'detail.copy': 'Kopiatu',
  'detail.copied': 'Kopiatuta',
  'detail.copyFailed': 'Ez da ezer kopiatu.',
  'detail.origin': 'Nondik sartu den',
  'detail.originUnknown': 'Ez dago jasota',
  'detail.package': 'Paketea',
  'detail.noPackage': 'Paketerik gabe',
  'detail.onDisk': 'Diskoan orain',
  'detail.onDiskHint': 'Fitxategiak segundo honetan diskoan neurtzen duena, zerbitzariari galdetuta eta ez hemen kontatuta. Martxan dagoen deskarga bat begirada batetik bestera hazten da, eta hau ez da ostalariak iragarritako tamaina.',
  'detail.mirrorOf': 'Honen ordezko kopia',
  'detail.times': 'Denbora-markak',
  'detail.timesHint': 'Esteka hau noiz iritsi zen, noiz aldatu zen azkenekoz eta noiz geratu zen eginda. Transferentzia noiz hasi zen ez dago hemen: aplikazioak ez du inoiz jaso, eta beste hiruretatik asmatutako balio bat jendeak gero erabiliko lukeen zenbaki bat litzateke.',
  'detail.nextTry': 'Hurrengo saiakera',
  'detail.stalledSince': 'Noiztik geldirik',
  'detail.retries': 'Orain arteko errepikapenak',
  'detail.retriesHint': 'Deskarga hau huts egin ondoren zenbat aldiz saiatu den berriro. Deskarga amaitzen den unean kontagailua zerora itzultzen da, beraz amaitutako errenkada batek zero erakusten du lau saiakera behar izan baditu ere. Zenbat saiakera geratzen diren ez da hemen ageri: goi-muga arrazoiaren eta ostalariaren araberakoa da, eta orri honek ezin du hori kalkulatu.',
  'detail.stallRestarts': 'Geldialdi osteko berrabiarazteak',
  'detail.stallRestartsHint': 'Geldialdien zaindariak zenbat aldiz abiarazi duen deskarga hau bere kabuz berriro. Deskarga amaitzean zerora itzultzen da, goiko kontagailua bezalaxe.',
  'detail.failure': 'Zer joan den gaizki',
  'detail.cause': 'Arrazoia',
  'detail.message': 'Zer esan duen backendak',
  'detail.messageHint': 'Hau ekartzen saiatu denaren esaldia, hitzez hitz eta itzuli gabe. Uneko hutsegitea da eta besterik ez: berrabiarazteak ezabatu egiten du, eta aurrekoak ez dira inon gordetzen.',
  'detail.heldBack': 'Zerk atxikitzen duen',
  'detail.doing': 'Orain zertan ari den',
  'detail.gaveUp': 'Ez da berriro saiatuko',
  'detail.gaveUpHint': 'Hemen nahita amaitu da, ez saiakerak agortu direlako: captcha bat, beteta dagoen disko bat, edo ostalari honentzat «inoiz ez» dioen arau bat. Errepikapen kopurua igotzeak ez du hemen ezer aldatzen. Marka bera ez da datu-basean idazten, beraz berrabiarazi ondoren desagertu egiten da, haren arrazoiak bere horretan jarraitzen duen arren.',
  'detail.rules': 'Hau moldatu duten arauak',
  'detail.rulesHint': 'Esteka hau prestatzean gainean exekutatu ziren arauak, exekutatu ziren hurrenkeran. Izenaren arabera gordetzen dira: ordutik berrizendatu den arau bat jada ez da aurkitzen, eta inoiz izenik izan ez duen arau bat orduan zuen kokapenarekin gordetzen da. Klik eginez gero, arauen editorean irekitzen da.',
  'detail.openRule': 'Ireki arauen editorean',
  'detail.noRules': 'Arau batek ere ez du esteka hau ukitu.',
  'detail.player': 'Erreproduzitu',
  'detail.play': 'Erreproduzitu hemen',
  'detail.playHint': 'Fitxategia zuzenean instantzia honetatik erreproduzitzen du, bigarren aldiz deskargatu gabe. Erreproduzitu sakatu arte ez da ezer ekartzen, eta fitxategia dagoen tokian geratzen da.',
  'detail.playPartial': 'Deskarga hau ez dago amaituta. Diskoan jada dagoen zatia bakarrik erreproduzi daiteke, hortik aurrera ezin da jauzi egin, eta fitxategi batzuek ez dute ezer erreproduzitzen azken bytea iritsi arte.',
  'detail.playUnsupported': 'Nabigatzaile honek ezin du fitxategi hau erreproduzitu. Ireki edo gorde ezazu eskuineko klikaren menutik.',
  'detail.playRemote': 'Instantzia honetako fitxategiak bakarrik erreproduzitzen dira hemen. Beste instantzia batek bere fitxategiak osorik eta jauzirik egin ezinik ematen ditu, eta erreproduzigailu batek ezin du horrekin lan egin.',
  'detail.playNotLocal': 'Deskarga hau JDownloader-ek ekarri du, beraz fitxategia prozesu horren diskoan dago eta ez honetan.',
  'detail.playNoFile': 'Oraindik ez dago diskoan erreproduzitzeko ezer.',
  'detail.playRefused': 'Zerbitzariak ez du fitxategi hau ematen: {reason}',
  'detail.playFailed': 'Erreprodukzioa gelditu da: {reason}',
  'detail.playClose': 'Itxi erreproduzigailua',

  'settings.rules.notFound': 'Hemen ez dago «{name}» izeneko araurik. Berrizendatu edo ezabatu egin da, hura izendatzen duen esteka gehitu zenetik.',

  'notifications.title': 'Jakinarazpenak',
  'notifications.titleHint': 'Erabaki gertaerarik gertaera aplikazioan burbuila gisa agertuko den, zure sistema eragilearen jakinarazpen gisa, edo batere ez. Sistemaren jakinarazpen bat KnightLoader-en fitxa bat irekita dagoen bitartean bakarrik iristen zaizu, eta beheko modu isila horren gainetik aplikatzen da.',
  'notifications.channel.app': 'Aplikazioan',
  'notifications.channel.system': 'Sistemaren jakinarazpena',
  'notifications.channel.silent': 'Ez erakutsi ezer',
  'notifications.event.downloadDone': 'Deskarga amaituta',
  'notifications.event.downloadDoneHint': 'Amaieraraino iristen den deskarga bakoitzak hala jakinarazten du. Ilaran berrehun fitxategi izateak berrehun jakinarazpen esan nahi du, beraz pentsa ezazu bi aldiz sistemara bidali aurretik.',
  'notifications.event.downloadFailed': 'Deskargak huts egin du',
  'notifications.event.downloadFailedHint': 'Amore eman duen deskarga bat. Modu isilak ez du inoiz hau ezkutatzen.',
  'notifications.event.extractionDone': 'Erauzketa amaituta',
  'notifications.event.extractionDoneHint': 'Erauzten amaitu den artxibo bat. Hau ez zen orain arte inon jakinarazten, beraz «Ez erakutsi ezer» aukeran hasten da.',
  'notifications.event.extractionFailed': 'Erauzketak huts egin du',
  'notifications.event.extractionFailedHint': 'Amaitu gabe eten den artxibo bat. Normalean pasahitza falta izaten da, eta fitxategiak dauden tokian geratzen dira zuk hori konpondu arte.',
  'notifications.event.captchaWaiting': 'Captcha bat zain dago',
  'notifications.event.captchaWaitingHint': 'Captcha-leihoa fitxa honetan irekitzen da nolanahi ere. «Ez erakutsi ezer» aukeran hasten da, leiho hori bera baita mezua zu begira zauden bitartean. Sistemaren jakinarazpena jarrita, atzeko planoko fitxa batean dagoen captcha bat ere iristen zaizu, ostalariak saioa bota aurretik.',
  'notifications.event.captchaFailed': 'Captchak huts egin du',
  'notifications.event.captchaFailedHint': 'Inork ez du garaiz erantzun, edo erantzuna ez da iritsi. Atzean dagoen deskarga dagoen tokian geratzen da.',
  'notifications.event.captchaResolved': 'Captcha beste nonbait ebatzita',
  'notifications.event.captchaResolvedHint': 'Beste nabigatzaile bateko norbaitek edo ebazle automatiko batek erantzun du, eta leihoa bere kabuz itxi da.',
  'notifications.systemUnavailable': 'Hemen ez dago sistemaren jakinarazpenik: nabigatzaileak HTTPS bidez edo localhost-en bakarrik eskaintzen ditu. Txartel honetako guztia aplikazioan erakusten da hala ere.',
  'notifications.systemBlocked': 'Nabigatzaileak helbide honetarako jakinarazpenak blokeatzen ditu. «Sistemaren jakinarazpena» ezarrita duten errenkadak aplikazioan erakusten dira haien ordez, zuk nabigatzailearen gune-ezarpenetan berriro baimendu arte.',
