  'views.clearAll': 'Garbitu bilaketa eta iragazki guztiak',
  'views.clearAllHint': 'Bilaketa eta iragazkiak ezarrita geratzen dira orritik atera eta itzultzean, beraz utzi zenuen zerrenda bera aurkitzen duzu. Honek zerrenda osoa ekartzen du berriro. Gordetako ikuspegiak dauden bezala geratzen dira.',

  'disk.title': 'Helmugako karpetak',
  'disk.hint': 'Deskarga bat amaitu daitekeen karpeta bakoitzeko leku librea eta erabilia, eta ilarak bakoitzean idazteko duena oraindik. Zenbakiak diskoaren mugak egiaztatzeko erabiltzen den dei beretik datoz, eta gehienez segundo gutxi batzuk dituzte. Libreak eta erabiliak ez dute beti bolumenaren tamaina osatzen: fitxategi-sistema batek zati bat gordetzen du sistemarentzat, eta erabiltzaileko kuota batek bolumenak benetan duena baino gutxiago utz diezaioke instantzia honi. Disko berean dauden bi karpetek disko hori erakusten dute biek, beraz ez batu inoiz errenkadak.',
  'disk.free': 'Libre',
  'disk.used': 'Erabilita',
  'disk.size': 'Diskoaren tamaina',
  'disk.queued': 'Idazteko dagoena',
  'disk.queuedHint': 'Oraindik zor diren deskargek karpeta honetara ekarriko luketena: ostalariak esandako tamaina, ken jada iritsi dena. Ostalariak tamaina esaten ez duen deskarga batek zero balio du hemen, beraz hau gutxieneko bat da eta inoiz ez promes bat, eta horregatik ager daiteke zero byte deskarga sail baten ondoan. Itzali dituzun deskargak kanpoan geratzen dira, zerrendaren azpiko kontagailuek jarraitzen duten arau bera. Jada martxan dagoen deskarga batek hasi zen unean gorde ohi du bere lekua diskoan, beraz haren byteak ondoko leku librearen zenbakian falta dira jada, eta ez dira honen gainera gehitzen.',
  'disk.tasks': '{n} deskarga',
  'disk.unknown': 'Sistema honek ez du leku librearen berri ematen',
  'disk.unknownHint': 'Nukleo guztiei ezin zaie galdetu bolumen batean zenbat leku geratzen den, eta build honek ez du exekutatzen ari den nukleorako deirik. Erantzuna falta den tokian ez da ezer atxikitzen: deskargak diskoaren mugarik ezarri gabe balego bezala hasten dira. Lerro hau hemen dago hori benetan beteta dagoen disko batetik bereizi ahal izan dezazun.',
  'disk.missing': 'Oraindik sortu gabe',
  'disk.missingHint': 'Karpeta hau bertan lehen fitxategia idazten duenak sortzen du, beraz oraindik ez dago hor. Zenbakiek {path} deskribatzen dute, gainean dagoen lehen karpeta existitzen dena, eta hori deskarga lurreratuko litzatekeen disko berean dago.',
  'disk.measured': 'Hemen neurtua: {path}',
  'disk.elsewhereHint': 'Karpeta bera ezin izan da neurtu, beraz gainean dagoen neurtu daitekeen lehena neurtu da. Muntatze-puntu bat igo ez bada, hori guztiz beste disko bat izan daiteke, deskargarentzat pentsatuta dagoena ez dena. Begiratu bideari zenbakietatik ondorioak atera aurretik.',
  'disk.sampled': 'Duela {n} segundo irakurria',
  'disk.tight': 'Ilara ez da kabitzen',
  'disk.tightHint': 'Karpeta honi diskoan libre dagoena baino gehiago zor zaio. Lerro honek berak ez du ezer gelditzen: deskargak banaka atxikitzen dira, bakoitza bere txandara iristean, Deskargen ezarpenen orriko zenbakien arabera, eta inork tamaina ezagutzen ez duen deskarga batek ez du hemen batere zenbatzen.',
  'disk.truncated': 'Ez daude karpeta guztiak zerrendan',
  'disk.truncatedHint': 'Ilarak ezarritakoetatik kanpo dauden karpeta gehiagotara jotzen du, irakurketa bakoitzean neurtzea merezi duena baino, beraz gutxien zor zaienak kanpoan geratu dira. Zuk ezarritako karpeta guztiak beti daude hemen.',
  'disk.markLow': 'Honen azpitik ez da ezer berririk hasten',
  'disk.markStop': 'Honen azpitik dena gelditzen da',
  'disk.limits': 'Ezarri diskoaren mugak',
  'disk.stripLabel': 'Lekua helmugako karpetetan',
  'disk.role.downloads': 'Deskargen karpeta',
  'disk.role.category': 'Kategoriaren karpeta',
  'disk.role.work': 'Lan-karpeta',
  'disk.role.task': 'Deskargan bertan ezarria',

  'settings.volume.title': 'Bolumen-muga',
  'settings.volume.titleHint': 'Instantzia honek amaieraraino zenbat deskargatu duen, zuk epe bakoitzeko ezartzen duzun muga baten aurka kontatuta. Amaitutako deskarga bakoitzeko ostalariak esandako tamaina zenbatzen da, beraz tamainarik esan gabe amaitzen dena zero da, eta torrent batek igotzen duenak ez du batere zenbatzen. Zure deskargen irakurketa bat da, ez zure linearen neurketa: hemen ezerk ezin ditu zure bideratzaileak benetan mugitu dituen byteak ikusi.',
  'settings.volume.cap': 'Epeko muga (GB)',
  'settings.volume.capHint': '0 balioak mugarik ez esan nahi du: kontagailuak aurrera jarraitzen du eta ez da inoiz ezer atxikitzen. Gigabyteak hamartarrak dira hemen, hornitzaile batek bere bolumena adierazten duen bezala: 500 GB 500 000 000 000 byte dira eta ez 465 GiB. Orri honetan goragoko diskoaren balioak GiB bitarrak dira, beste galdera batentzako beste unitate bat.',
  'settings.volume.resetDay': 'Kontagailua berriro hasten den eguna',
  'settings.volume.resetDayHint': 'Hilabeteko zein egunetan itzultzen den kontagailua zerora, normalean zure bolumena berritzen den eguna. Aukeratutako eguna baino laburragoa den hilabete batean, hilabete horretako azken egunean hasten da berriro, eta ez da inoiz hurrengora pasatzen. Zerbitzariaren ordulariaren arabera kontatzen da, eta ez zure nabigatzailearenaren arabera, zerbitzaria baita ilara atxikitzen duena.',
  'settings.volume.action': 'Mugara iristean',
  'settings.volume.actionHint': 'Jada martxan dagoen transferentzia bat ez da inoiz eteten, edozein erantzun aukeratuta ere: fitxategi baten erdian gelditzeak jada gastatu dituzun byteak botatzen ditu. «Jakinarazi besterik ez» aukerak ez du ezer aldatzen, eta orduan kontagailua da funtzio osoa. «Ez hasi deskarga gehiago» aukerak martxan dagoena amaitzen uzten du eta ilara atxikitzen du kontagailua berriro hasi arte, eta zain dagoen errenkada bakoitzak hala dio. «Moteldu dena» aukerak ilarak aurrera jarraitzen uzten du, beheko abiaduran.',
  'settings.volume.actionReport': 'Jakinarazi besterik ez',
  'settings.volume.actionPause': 'Ez hasi deskarga gehiago',
  'settings.volume.actionThrottle': 'Moteldu dena',
  'settings.volume.throttle': 'Abiadura muga gainditu ondoren',
  'settings.volume.throttleHint': 'Epearen gainerakoan aplikatzen den muga. Zure beste mugen ondoko goi-muga bat da eta inoiz ez haien ordezkoa: gutxiago eskatzen duten gaueko leiho batek edo modu isilaren etengailuak irabazten jarraitzen dute. Hemen 0 jartzeak mugarik batere ez izatea esan nahiko luke, eta hori mugarik ez izatea bera da, beraz zenbaki baliagarririk txikiena 1 da.',
  'settings.volume.noCap': 'Mugarik ez',
  'settings.volume.used': 'Epe honetan deskargatuta',
  'settings.volume.usedOf': '{cap}(e)tik {used}',
  'settings.volume.resetsOn': 'Berriro hasten da: {date}',
  'settings.volume.reached': 'Mugara iritsi da.',

  'volume.title': 'Deskargatutako bolumena',
  'volume.titleHint': 'Amaitutako deskargak egunez egun eta hilabetez hilabete batuta, deskargen historiatik hartuta. Historiak bere goi-muga du eta eskuz hustu daiteke, beraz hortik erori diren hilabeteak ez daude hemen. Berrabiarazi duzun deskarga batek behin zenbatzen du, azkenekoz amaitu zen egunean. Egutegia zerbitzariarena da, {zone} ordu-eremuan.',
  'volume.range.days': '30 egun',
  'volume.range.months': '12 hilabete',
