  'volume.other': 'Gainerako guztia',
  'volume.empty': 'Epe honetan ez da oraindik ezer amaitu.',
  'volume.unsizedHint': 'Deskarga hauetatik {n} ostalariak inoiz tamainarik esan gabe amaitu dira. Ez diote ezer gehitzen guztizkoari, beraz benetako zenbakia hemen marraztutakoa baino handiagoa da.',
  'volume.trimmedHint': 'Historia bere mugan dago, beraz haren sarrerarik zaharrena baino lehenagoko guztia kurba honetan ere falta da. Igo historiaren goi-muga orri honetan atzerago begiratu nahi baduzu.',
  'volume.meter': 'Bolumena',
  'volume.meterHint': 'Kontagailua azkenekoz berrabiarazi zenetik deskargatzen amaitu dena, Deskargak ezarpen-orriko goi-mugarekin alderatuta. Zenbakia deskarga bat amaitzen denean mugitzen da, ez martxan dagoen bitartean. Deskarga-historiatik batzen da, beraz historia husteak kontagailu hau ere zerora jartzen du.',
