  'settings.selftest.status.unknown': 'Ezin da jakin',
  'settings.selftest.jd': 'JDownloader atzealdea',
  'settings.selftest.jd.ok': 'Iristeko moduan, {version} berrikuspena.',
  'settings.selftest.jd.provisioningOff': 'Hornikuntza itzalita dago eta ez dago helbiderik ezarrita, beraz ez dago iristeko backendik.',
  'settings.selftest.jd.missing': 'Ez dago backend helbiderik. DLC eta edukiontzi-esteka zifratuak baztertu egiten dira.',
  'settings.selftest.jd.missingAdvice': 'Build honek normalean bere headless JDownloader propioa abiarazten du hastean, eta KL_JD berak betetzen du. Hutsik egoteak esan nahi du abiarazte hori huts egin duela. Bilatu "JD provisioning failed" beheragoko erregistroan, edo ezarri KL_JD zure JDownloader batera.',
  'settings.selftest.jd.unreachable': '{address} helbideak ez du erantzun.',
  'settings.selftest.jd.unreachableAdvice': 'Helbidea gordeta dago, baina ezer ez dago bertan entzuten. Egiaztatu backenda martxan dagoela, eta haren 3128 ataka edukiontzi honen barrutik iristeko moduan dagoela, ez ostalaritik bakarrik.',
  'settings.selftest.jd.noVersion': 'Erantzuten du, baina ez du esaten zein berrikuspen den.',
  'settings.selftest.ytdlp': 'yt-dlp',
  'settings.selftest.ytdlp.ok': '{version}, {days} egunekoa.',
  'settings.selftest.ytdlp.aging': '{version} bertsioak {days} egun ditu.',
  'settings.selftest.ytdlp.old': '{version} bertsioak {days} egun ditu. Bideo-gune handiek aste gutxitan hondatzen dute normalean.',
  'settings.selftest.ytdlp.oldAdvice': 'Edukiontzian, yt-dlp irudia eraiki zenean indarrean zegoen Alpine paketetik dator, eta ez da inoiz bere kabuz eguneratzen. Ekarri irudi berriago bat, edo muntatu zure yt-dlp bat edukiontzian eta seinalatu KL_YTDLP hara.',
  'settings.selftest.ytdlp.missing': 'Ez da aurkitu, beraz multimedia-orriek ostalariaren beraren errorearekin huts egiten dute.',
  'settings.selftest.ytdlp.missingAdvice': 'Seinalatu KL_YTDLP fitxategi bitarrera, edo jarri yt-dlp PATHean. Behin bakarrik bilatzen da abiatzean, beraz orain instalatutako bat berrabiarazi ondoren bakarrik erabiltzen da.',
  'settings.selftest.ytdlp.undated': '{version} ez da data baten itxurakoa, beraz ezin da haren adina epaitu.',
  'settings.selftest.folders': 'Deskargen karpeta eta lan-karpeta',
  'settings.selftest.folders.allOk': 'Egiaztatutako karpeta bakoitza han dago eta bertan idatz daiteke.',
  'settings.selftest.folders.someBad': 'Gutxienez karpeta batean bada zerbait begiratzeko.',
  'settings.selftest.folders.none': 'Ez da karpeta bakar bat ere neurtu ahal izan.',
  'settings.selftest.folders.ok': '{dir} karpetan idatz daiteke, {free} libre.',
  'settings.selftest.folders.notWritable': '{dir} karpetan ezin da idatzi.',
  'settings.selftest.folders.notWritableAdvice': 'Prozesu honen uid-a {uid} da. Begiratu karpeta hori ostalarian norena den eta uid horrek bertan idatz dezakeen.',
  'settings.selftest.folders.missing': '{dir} oraindik ez dago, beraz zenbakiek {measured} deskribatzen dute.',
  'settings.selftest.folders.missingAdvice': 'Hori normala da oraindik ezer idatzi ez zaion karpeta batean, eta lehen deskargak sortzen du. Baina {measured} bolumenaren erroa bada, espero zenuen muntaia falta da, eta deskarga edukiontzi barruan amaitzen du, zure diskoan beharrean.',
  'settings.selftest.folders.low': '{dir} karpetan {free} besterik ez da geratzen, ilara gelditzen den {mark} mugaren azpitik.',
  'settings.selftest.folders.noMark': '{free} libre {dir} karpetan. Ez duzu atalase finkorik ezarri, beraz ilarak dagoeneko sartzen ez den deskarga bat baino ez du atxikitzen.',
  'settings.selftest.folders.unknown': 'Plataforma honi ezin zaio galdetu {dir} karpetan zenbat leku dagoen.',
  'settings.selftest.accounts': 'Debrid saio-hasierak',
  'settings.selftest.accounts.none': 'Ez dago debrid konturik konfiguratuta, beraz ez zegoen ezer egiaztatzeko.',
