  'auth.passkey.title': 'Sarbide-gakoak',
  'auth.passkey.hint': 'Zure telefonoak, ordenagailu eramangarriak edo segurtasun-gakoak gordetzen duen gako batek pasahitza idatzi gabe sartzen zaitu. Barrurako bide gehigarri bat da: pasahitzak balio du oraindik, eta sarbide-gako guztiak kentzeak ez du inor kanpoan uzten. Sarbide-gako bat sortu zen web helbidearena da, beraz proxy baten bidez erregistratutakoak ez du funtzionatzen sare lokaleko helbidean, ez eta alderantziz ere.',
  'auth.passkey.registered': '{n} erregistratuta',
