  'auth.passkey.needsPassword': 'Ezarri pasahitz bat lehenengo. Sarbide-gakoa saio-hasiera baterako bigarren bidea da, beraz bat egon behar da.',
  'auth.passkey.unavailableTitle': 'Sarbide-gakoek ostalari-izena behar dute, eta orri hau IP helbide batean dago irekita.',
  'auth.passkey.unavailableReason': 'Sarbide-gako bat domeinu bati lotuta dago, beraz nabigatzaileek trukea osorik ukatzen dute helbide huts batean, eta berriro ukatzen dute fidatzen ez diren ziurtagiri batekin. Iritsi KnightLoaderera alderantzizko proxy baten bidez izen erreal batekin eta baliozko ziurtagiriarekin, ireki hor eta erregistratu gakoa helbide horretan.',
  'auth.passkey.noBrowserTitle': 'Nabigatzaile honek ez du sarbide-gakorik eskaintzen.',
